SELECT cc.cc_name AS call_center_name, t_cr.t_hour AS catalog_return_hour, c.c_salutation AS salutation, COUNT(DISTINCT cr.cr_order_number) AS catalog_return_orders, SUM(cr.cr_return_amount) AS total_catalog_return_amount, AVG(cr.cr_return_amount) AS avg_catalog_return_amount, (SELECT AVG(cr2.cr_return_amount) FROM catalog_returns cr2) AS overall_avg_return_amount, SUM(sr.sr_return_amt) AS total_store_return_amount, AVG(sr.sr_fee) AS avg_store_fee, MIN(cr.cr_return_tax) AS min_return_tax, MAX(sr.sr_net_loss) AS max_store_net_loss, COUNT(*) AS total_rows FROM catalog_returns cr JOIN call_center cc ON cr.cr_call_center_sk = cc.cc_call_center_sk JOIN time_dim t_cr ON cr.cr_returned_time_sk = t_cr.t_time_sk JOIN customer c ON cr.cr_returning_customer_sk = c.c_customer_sk JOIN store_returns sr ON sr.sr_customer_sk = c.c_customer_sk JOIN time_dim t_sr ON sr.sr_return_time_sk = t_sr.t_time_sk WHERE cc.cc_call_center_sk = 20 AND cr.cr_return_amount > 500.00 AND cr.cr_return_quantity >= 2 AND c.c_birth_day = 14 AND c.c_salutation = 'Mrs.' AND t_cr.t_hour BETWEEN 9 AND 17 AND sr.sr_fee < 50.00 AND sr.sr_net_loss > 100.00 AND t_sr.t_meal_time = 'Lunch' GROUP BY cc.cc_name, t_cr.t_hour, c.c_salutation ORDER BY total_catalog_return_amount DESC LIMIT 100
